def normalize(path):
    if not path:
        return '.'
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            elif not is_abs:
                stack.append('..')
        else:
            stack.append(part)
    if not stack:
        return '/' if is_abs else '.'
    result = '/'.join(stack)
    if is_abs:
        result = '/' + result
    return result

