def parse_csv(text):
    lines = text.strip().splitlines()
    if not lines:
        return []
    header = lines[0].split(',')
    result = []
    for line in lines[1:]:
        fields = []
        i = 0
        n = len(line)
        while i < n:
            if line[i] == '"':
                j = i + 1
                while j < n:
                    if line[j] == '"':
                        if j + 1 < n and line[j + 1] == '"':
                            j += 2
                        else:
                            break
                    j += 1
                if j == n:
                    raise ValueError("Unterminated quoted field")
                fields.append(line[i + 1:j].replace('""', '"'))
                i = j + 1
                if i < n and line[i] == ',':
                    i += 1
            else:
                j = i
                while j < n and line[j] != ',':
                    j += 1
                fields.append(line[i:j])
                i = j + 1
        if len(fields) != len(header):
            raise ValueError("Field count mismatch")
        result.append(dict(zip(header, fields)))
    return result

