def parse_duration(s):
    if not s:
        raise ValueError("Empty string")
    total = 0
    i = 0
    n = len(s)
    while i < n:
        # parse numeric part
        start = i
        while i < n and s[i].isdigit():
            i += 1
        if i == start:
            raise ValueError(f"Missing number at position {start}")
        num = int(s[start:i])
        # parse unit part
        if i >= n:
            raise ValueError(f"Missing unit after number at position {start}")
        unit = s[i]
        i += 1
        # map unit to seconds
        if unit == 's':
            sec = 1
        elif unit == 'm':
            sec = 60
        elif unit == 'h':
            sec = 3600
        elif unit == 'd':
            sec = 86400
        else:
            raise ValueError(f"Unknown unit '{unit}'")
        total += num * sec
    return total

