def strip_comments(code):
    result = []
    in_single = False
    in_double = False
    escape = False
    i = 0
    while i < len(code):
        ch = code[i]
        if escape:
            escape = False
        elif ch == '\\':
            escape = True
        elif ch == "'" and not in_double:
            in_single = not in_single
        elif ch == '"' and not in_single:
            in_double = not in_double
        elif ch == '#' and not in_single and not in_double:
            break
        result.append(ch)
        i += 1
    return ''.join(result)

