import hashlib
import json

def stable_hash(obj):
    """
    Return a stable hex hash for nested dict/list/str/int structures.
    The hash is independent of dict key insertion order.
    """
    def _encode(o):
        if isinstance(o, dict):
            # Sort items by key to ensure order‑independence
            return json.dumps(o, sort_keys=True, separators=(',', ':'))
        elif isinstance(o, (list, tuple)):
            return json.dumps(o, separators=(',', ':'))
        elif isinstance(o, (str, int)):
            return json.dumps(o, separators=(',', ':'))
        else:
            raise TypeError(f"Unsupported type: {type(o)}")

    data = _encode(obj).encode('utf-8')
    return hashlib.sha256(data).hexdigest()
```

