function debounceCount(fn, ms) {
  let timer = null;
  let pending = false;

  const call = () => {
    pending = true;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      fn();
      pending = false;
    }, ms);
  };

  const flush = () => {
    if (timer) {
      clearTimeout(timer);
      if (pending) {
        fn();
        pending = false;
      }
    }
  };

  return { call, flush };
}

module.exports = debounceCount;
```

